// Написан вручную (запасной путь: MCP-генератор не нашёл seed). Селекторы сверены на живой странице через playwright-cli
// (iPhone 13 Mini, free, 2026-10-29), сам тест не прогонялся — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/location-map.md 2.2 · кейс .qa/tests/location-map/IND-02.md
// seed: tests/seed.free.geo.spec.ts
// Шит «דייט עכשיו» только открывается и закрывается (Escape) — режим не включается. В конце шаринг выключается.
import { test, expect } from '@playwright/test';
import path from 'path';
import { enableSharing, disableSharing } from './map-helpers';
import { saveSession } from '../_shared/session';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free.json'),
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  geolocation: { latitude: 32.0853, longitude: 34.7818, accuracy: 10 },
  permissions: ['geolocation'],
});

const PILL = 'שיתוף מיקום פעיל';

test.describe('Индикатор шаринга местоположения', () => {
  test('Шаринг включён — индикатор на /map (и после перезагрузки), /nearby, в шите Date Now @iphone @data (#5f64d4)', async ({ page }) => {
    try {
      // 1. Предусловие — выключен; включить кнопкой «הפעלת שיתוף מיקום» (enableSharing ждёт PATCH share_location=true, 2xx)
      await disableSharing(page);
      await enableSharing(page);
      await expect(page.getByRole('switch', { name: PILL })).toBeVisible();

      // 2. После перезагрузки индикатор остаётся (AC 1)
      await page.reload();
      await expect(page.getByRole('switch', { name: PILL })).toBeVisible();

      // 3. /nearby — индикатор виден (AC 4)
      await page.goto('/nearby');
      await expect(page.getByText(PILL, { exact: true })).toBeVisible();

      // 4. /map → шит «דייט עכשיו»: сверху пилюля «שיתוף מיקום פעיל» (AC 4; Figma 869-7494); закрыть, не включая
      await page.goto('/map');
      await expect(page.getByRole('switch', { name: PILL })).toBeVisible();
      await page.getByRole('button', { name: 'דייט עכשיו' }).first().click();
      const sheet = page.getByRole('dialog').filter({ hasText: 'פנוי/ה לדייט עכשיו?' });
      await expect(sheet).toBeVisible();
      await expect(sheet.getByRole('button', { name: PILL })).toBeVisible();
      await page.keyboard.press('Escape');
      await expect(sheet).toBeHidden();
    } finally {
      // 5. Очистка: шаринг → false
      await disableSharing(page).catch(() => {});
      await saveSession(page, 'free');
    }
  });
});
